import type { SubjectId } from './archive';

/**
 * Standard JSON schema for daily/weekly 100-mark MCQ quizzes generated by
 * Gemini Tasks and uploaded into each subject's Google Drive quiz folder.
 */
export interface QuizQuestion {
  id: string;
  chapter: string;
  standardRef?: string;
  caseScenario?: string;
  question: string;
  options: [string, string, string, string] | string[];
  correctOptionIndex: number;
  marks: number;
  explanation: string;
}

export interface QuizDataset {
  id: string;
  title: string;
  subjectId: SubjectId;
  publishedDate: string;
  cadence: 'daily' | 'weekly' | 'chapter-drill';
  totalMarks: number;
  durationMinutes: number;
  negativeMarking?: number;
  generatedBy?: string;
  questions: QuizQuestion[];
}

export interface ChapterScoreBreakdown {
  chapter: string;
  earnedMarks: number;
  totalMarks: number;
  correctCount: number;
  questionCount: number;
}

export interface QuizResultSummary {
  earnedMarks: number;
  totalMarks: number;
  percentage: number;
  correctCount: number;
  incorrectCount: number;
  unansweredCount: number;
  chapterBreakdown: ChapterScoreBreakdown[];
}

/**
 * Future Descriptive Answer Analysis schema for typed or PDF answer uploads
 * stored in the owner's private Drive and analyzed asynchronously by Gemini Argon tasks.
 */
export interface DescriptiveQuestion {
  id: string;
  subjectId: SubjectId;
  chapter: string;
  standardRef: string;
  marks: number;
  prompt: string;
  caseFacts: string[];
  expectedChecklist: string[];
}

export interface DescriptiveSubmissionRecord {
  trackingId: string;
  questionId: string;
  questionTitle: string;
  subjectId: SubjectId;
  studentName: string;
  studentEmail?: string;
  mode: 'typed' | 'pdf';
  typedAnswer?: string;
  pdfFileName?: string;
  pdfSizeBytes?: number;
  submittedAt: string;
  status: 'queued-for-analysis' | 'evaluated';
  deliveryMode: 'apps-script' | 'local-preview';
  evaluation?: DescriptiveEvaluationResult;
}

export interface DescriptiveEvaluationResult {
  trackingId: string;
  evaluatedAt: string;
  awardedMarks: number;
  maxMarks: number;
  summaryVerdict: string;
  correctPoints: string[];
  missingOrIncorrectPoints: string[];
  standardReferencesCited: string[];
  improvementGuidance: string;
}
